'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync, spawnSync } = require('node:child_process');
const { readDiff, evaluateDiff } = require('../scripts/no-destroy-guard');
const root = path.resolve(__dirname, '..');
const script = path.join(root, 'scripts/no-destroy-guard.js');

// Only disposable fixtures generated by this test are cleaned up; repository
// source work is never deleted. Fixtures stay inside the authorized worktree.
function fixture(t) {
  const cwd = fs.mkdtempSync(path.join(root, 'docs/security-completion/.git-fixture-'));
  t.after(() => fs.rmSync(cwd, { recursive: true, force: true }));
  const git = (...args) => execFileSync('git', args, {
    cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'],
    env: { ...process.env, GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: '/dev/null' },
  }).trim();
  git('init', '-b', 'main');
  git('config', 'user.name', 'Security Fixture');
  git('config', 'user.email', 'fixture@example.invalid');
  const write = (name, text) => {
    fs.mkdirSync(path.dirname(path.join(cwd, name)), { recursive: true });
    fs.writeFileSync(path.join(cwd, name), text);
  };
  const commit = () => { git('add', '--', '.'); git('commit', '-m', 'test: fixture'); return git('rev-parse', 'HEAD'); };
  return { cwd, git, write, commit };
}

function lines(n, prefix = 'original') { return Array.from({ length: n }, (_, i) => `${prefix} ${i}\n`).join(''); }

test('NUL-safe path records preserve tabs, newlines, spaces, Unicode and leading dashes', (t) => {
  const f = fixture(t);
  const names = ['docs/tab\tname.md', 'docs/line\nname.md', 'docs/space name.md', 'docs/café.md', '-leading.md'];
  for (const name of names) f.write(name, lines(25));
  const base = f.commit();
  for (const name of names) f.write(name, lines(25) + 'addition\n');
  const head = f.commit();
  const diff = readDiff(base, head, { cwd: f.cwd });
  assert.deepEqual(new Set(diff.map((x) => x.path)), new Set(names));
  assert.ok(diff.every((x) => x.beforeLines === 25 && x.deleted === '0' && x.added === '1'));
  assert.equal(evaluateDiff(diff).fail, false);
});

test('merge-base excludes new base-branch files from PR deletion totals', (t) => {
  const f = fixture(t);
  f.write('original.md', lines(30));
  const common = f.commit();
  f.git('checkout', '-b', 'feature');
  f.write('feature.md', 'feature\n');
  const head = f.commit();
  f.git('checkout', 'main');
  f.write('base-only.md', lines(2000));
  const base = f.commit();
  assert.notEqual(common, base);
  const diff = readDiff(base, head, { cwd: f.cwd });
  assert.deepEqual(diff.map((x) => x.path), ['feature.md']);
  assert.equal(evaluateDiff(diff).fail, false);
});

test('renames are exposed as prohibited deletion plus addition', (t) => {
  const f = fixture(t);
  f.write('old.md', lines(30));
  const base = f.commit();
  f.git('mv', 'old.md', 'new.md');
  const diff = readDiff(base, f.commit(), { cwd: f.cwd });
  assert.ok(diff.some((x) => x.path === 'old.md' && x.status === 'D'));
  assert.equal(evaluateDiff(diff).fail, true);
});

test('large replacement and stripping are caught below the global line budget', (t) => {
  const f = fixture(t);
  f.write('tool.js', lines(50));
  const base = f.commit();
  f.write('tool.js', lines(50, 'replacement'));
  const diff = readDiff(base, f.commit(), { cwd: f.cwd });
  assert.equal(evaluateDiff(diff).fail, true);
  assert.ok(evaluateDiff(diff).reasons.some((x) => /50\/50/.test(x)));
});

test('binary modification and file type changes do not appear as quantified safe edits', (t) => {
  const f = fixture(t);
  f.write('blob.bin', Buffer.from([0, 1, 2, 3]));
  const base = f.commit();
  f.write('blob.bin', Buffer.from([0, 9, 8, 7]));
  assert.equal(evaluateDiff(readDiff(base, f.commit(), { cwd: f.cwd })).fail, true);
  assert.equal(evaluateDiff([{ path: 'tool', status: 'T', added: '1', deleted: '1' }]).fail, true);
});

test('unknown commits and unrelated histories fail closed', (t) => {
  const f = fixture(t);
  f.write('original.md', 'one\n');
  const base = f.commit();
  assert.throws(() => readDiff('not-a-commit', base, { cwd: f.cwd }));
  f.git('checkout', '--orphan', 'unrelated');
  f.write('new.md', 'two\n');
  assert.throws(() => readDiff(base, f.commit(), { cwd: f.cwd }));
});

test('missing baseline, malformed threshold and ALLOW_DESTROY cannot return CLI success', (t) => {
  const env = { ...process.env };
  delete env.BASE_SHA;
  let r = spawnSync(process.execPath, [script], { cwd: root, env, encoding: 'utf8' });
  assert.equal(r.status, 1);
  const f = fixture(t);
  f.write('docs/preserve.md', 'one\n');
  const base = f.commit();
  // git rm only deletes this test-generated disposable fixture, never source work.
  f.git('rm', '--', 'docs/preserve.md');
  f.write('replacement.md', 'new\n');
  const head = f.commit();
  for (const extra of [{ ALLOW_DESTROY: 'true' }, { MAX_GLOBAL_DELETED: 'garbage' }, { REPLACEMENT_RATIO: 'NaN' }]) {
    r = spawnSync(process.execPath, [script], {
      cwd: f.cwd, env: { ...env, BASE_SHA: base, HEAD_SHA: head, ...extra }, encoding: 'utf8',
    });
    assert.equal(r.status, 1);
  }
});

test('replacement minimum, ratio, aggregation and exact deletion threshold boundaries', () => {
  const edit = (beforeLines, deleted) => [{ path: 'docs/change.md', beforeLines, deleted: String(deleted), added: '1', status: 'M' }];
  assert.equal(evaluateDiff(edit(19, 19)).fail, false);
  assert.equal(evaluateDiff(edit(20, 15)).fail, false);
  assert.equal(evaluateDiff(edit(20, 16)).fail, true);
  assert.equal(evaluateDiff(edit(2000, 1000)).fail, false);
  assert.equal(evaluateDiff(edit(2000, 1001)).fail, true);
  assert.equal(evaluateDiff([
    { path: 'docs/one.md', deleted: '600', added: '1', status: 'M' },
    { path: 'data/two.txt', deleted: '401', added: '1', status: 'M' },
  ]).fail, true);
  assert.throws(() => evaluateDiff([], { maxGlobalDeleted: NaN }));
  assert.throws(() => evaluateDiff([], { replacementRatio: 2 }));
});
